<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>The Morning Alpaca</title>
<style>
  * { margin:0; padding:0; box-sizing:border-box; }
  html, body { width:100%; height:100%; overflow:hidden; background:#9ed7f2; font-family:Georgia, "Times New Roman", serif; }
  .stage { position:fixed; inset:0; width:100vw; height:100vh; overflow:hidden; }
  svg { display:block; width:100%; height:100%; }

  .caption {
    position:absolute; left:52px; top:42px; color:#31536b; pointer-events:none;
    text-shadow:0 1px 0 rgba(255,255,255,.55);
  }
  .caption .small {
    font-family:Arial, Helvetica, sans-serif; font-size:11px; letter-spacing:.34em;
    text-transform:uppercase; color:#6d8a78; margin-bottom:9px; font-weight:700;
  }
  .caption h1 { font-size:42px; line-height:.95; font-weight:400; font-style:italic; letter-spacing:-.02em; }
  .caption p { margin-top:10px; font-size:16px; font-style:italic; color:#67808a; }
  .vignette {
    position:absolute; inset:0; pointer-events:none;
    background:radial-gradient(ellipse at 50% 42%, transparent 52%, rgba(64,84,74,.16) 100%);
  }

  /* ---------- sky motion ---------- */
  .cloud-drift { animation:cloudDrift 9s ease-in-out infinite alternate; }
  .cloud-drift.slow { animation-duration:13s; animation-delay:-4s; }
  @keyframes cloudDrift { from { transform:translateX(-18px); } to { transform:translateX(28px); } }

  .rays { transform-box:fill-box; transform-origin:center; animation:spinRays 46s linear infinite; opacity:.5; }
  @keyframes spinRays { to { transform:rotate(360deg); } }

  .bird-bob { animation:birdBob 2.8s ease-in-out infinite alternate; }
  .bird-bob.two { animation-delay:-1.3s; }
  @keyframes birdBob { from { transform:translateY(0); } to { transform:translateY(-9px); } }

  /* ---------- scrolling ground ---------- */
  .scroll-fast { animation:scrollGround 5.2s linear infinite; }
  .scroll-mid  { animation:scrollGround 9s linear infinite; }
  @keyframes scrollGround { from { transform:translateX(0); } to { transform:translateX(-1280px); } }

  /* ---------- alpaca body ---------- */
  .bob { animation:bob 1.6s ease-in-out infinite; }
  @keyframes bob {
    0%,50%,100% { transform:translateY(0); }
    25%,75%     { transform:translateY(-5px); }
  }
  .shadow-pulse { transform-box:fill-box; transform-origin:center; animation:shadowPulse 1.6s ease-in-out infinite; }
  @keyframes shadowPulse {
    0%,50%,100% { transform:scaleX(1); opacity:.22; }
    25%,75%     { transform:scaleX(.94); opacity:.17; }
  }
  .breath { transform-box:fill-box; transform-origin:50% 60%; animation:breath 1.6s ease-in-out infinite; }
  @keyframes breath {
    0%,50%,100% { transform:scale(1,1); }
    25%,75%     { transform:scale(1.012,1.02); }
  }

  .neck-swing { transform-box:fill-box; transform-origin:28% 92%; animation:neckSwing 1.6s ease-in-out infinite; }
  @keyframes neckSwing {
    0%,100% { transform:rotate(1.6deg); }
    25%     { transform:rotate(-1.8deg); }
    50%     { transform:rotate(1.6deg); }
    75%     { transform:rotate(-1.8deg); }
  }
  .head-swing { transform-box:fill-box; transform-origin:8% 78%; animation:headSwing 1.6s ease-in-out infinite; }
  @keyframes headSwing {
    0%,100% { transform:rotate(-2deg) translateY(0); }
    25%     { transform:rotate(2.4deg) translateY(2px); }
    50%     { transform:rotate(-2deg) translateY(0); }
    75%     { transform:rotate(2.4deg) translateY(2px); }
  }
  .ear-wiggle { transform-box:fill-box; transform-origin:50% 100%; animation:earWiggle 3.2s ease-in-out infinite; }
  .ear-wiggle.back { animation-delay:-1.6s; }
  @keyframes earWiggle {
    0%,88%,100% { transform:rotate(0deg); }
    92% { transform:rotate(-8deg); }
    96% { transform:rotate(6deg); }
  }
  .eye { transform-box:fill-box; transform-origin:center; animation:blink 4.8s ease-in-out infinite; }
  @keyframes blink {
    0%,91%,98%,100% { transform:scaleY(1); }
    94% { transform:scaleY(.08); }
  }
  .tail-wag { transform-box:fill-box; transform-origin:90% 45%; animation:tailWag 1.6s ease-in-out infinite; }
  @keyframes tailWag {
    0%,100% { transform:rotate(4deg); }
    50%     { transform:rotate(-7deg); }
  }
  .fringe { transform-box:fill-box; transform-origin:50% 0%; animation:fringeSway 1.6s ease-in-out infinite; }
  @keyframes fringeSway {
    0%,100% { transform:rotate(2deg); }
    50%     { transform:rotate(-3deg); }
  }

  /* ---------- walking legs : four-beat gait ---------- */
  .swing { transform-box:fill-box; transform-origin:50% 0%; animation:swing 1.6s ease-in-out infinite; }
  @keyframes swing {
    0%,100% { transform:rotate(23deg); }
    50%     { transform:rotate(-23deg); }
  }
  .bend { transform-box:fill-box; transform-origin:50% 0%; animation:bend 1.6s ease-in-out infinite; }
  @keyframes bend {
    0%,100% { transform:rotate(3deg); }
    42%     { transform:rotate(5deg); }
    55%     { transform:rotate(0deg); }
    70%     { transform:rotate(38deg); }
    86%     { transform:rotate(16deg); }
  }
  /* footfall order: near-front, far-hind, far-front, near-hind */
  .p1 .swing, .p1 .bend { animation-delay:0s; }
  .p2 .swing, .p2 .bend { animation-delay:-.4s; }
  .p3 .swing, .p3 .bend { animation-delay:-.8s; }
  .p4 .swing, .p4 .bend { animation-delay:-1.2s; }

  .puff { transform-box:fill-box; transform-origin:center; animation:puff 1.6s ease-out infinite; opacity:0; }
  .puff.two { animation-delay:-.8s; }
  @keyframes puff {
    0%,52% { transform:translate(0,0) scale(.4); opacity:0; }
    60%    { opacity:.45; }
    82%,100% { transform:translate(-26px,-10px) scale(1.35); opacity:0; }
  }

  .pollen-dot { animation-name:pollenFloat; animation-timing-function:ease-in-out; animation-iteration-count:infinite; }
  @keyframes pollenFloat {
    0%   { transform:translate(0,0); opacity:0; }
    18%  { opacity:.85; }
    82%  { opacity:.6; }
    100% { transform:translate(-72px,-48px); opacity:0; }
  }
</style>
</head>
